public class ClassFileVersion implements Comparable<ClassFileVersion>, Serializable {
    @Override
    public String toString() {
        ClassFileVersion[] versions = {JAVA_V8, JAVA_V11, JAVA_V17, JAVA_V21};
        String report = "";
        for (ClassFileVersion v : versions) {
            if (isAtLeast(v)) {
                report += "compatible:" + v.getJavaVersion() + " ";
            }
        }
        return "ClassFileVersion{major=" + getMajorVersion() + ", " + report + "}";
    }

